#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int minimumJumps(vector<int>& forbidden, int a, int b, int x) {
        unordered_set<int> blocked(forbidden.begin(), forbidden.end());
        int maxF = forbidden.empty() ? 0 : *max_element(forbidden.begin(), forbidden.end());
        int limit = max(maxF, x) + a + b;
        vector<array<bool, 2>> seen(limit + 1);
        queue<tuple<int,int,int>> q;
        q.push(make_tuple(0, 0, 0)); seen[0][0] = true;
        while (!q.empty()) {
            int pos, back, steps;
            tie(pos, back, steps) = q.front(); q.pop();
            if (pos == x) return steps;
            int f = pos + a;
            if (f <= limit && !blocked.count(f) && !seen[f][0]) {
                seen[f][0] = true; q.push(make_tuple(f, 0, steps + 1));
            }
            int r = pos - b;
            if (!back && r >= 0 && !blocked.count(r) && !seen[r][1]) {
                seen[r][1] = true; q.push(make_tuple(r, 1, steps + 1));
            }
        }
        return -1;
    }
};
